import React, { useEffect, useState } from 'react'
import { createRoot } from 'react-dom/client'
import { Activity, AlertTriangle, ArrowDown, ArrowRight, BarChart3, CheckCircle2, ChevronRight, CircleHelp, ClipboardCheck, Clock3, Database, FlaskConical, GitBranch, LayoutDashboard, ListChecks, LoaderCircle, Network, Play, RotateCcw, Search, ShieldCheck, Siren, Wrench, X, Zap } from 'lucide-react'
import './styles.css'

const API = '/api'
async function request(path, options={}) {
  const res = await fetch(API + path, {headers:{'Content-Type':'application/json'}, ...options})
  const body = await res.json().catch(()=>({detail:'Invalid server response'}))
  if (!res.ok) throw new Error(typeof body.detail === 'string' ? body.detail : JSON.stringify(body.detail))
  return body
}
const iconFor = (name) => name.includes('Database') ? Database : name.includes('Network') ? Network : name.includes('Application') ? Zap : name.includes('queue') || name.includes('Queue') ? Activity : name.includes('config') || name.includes('Configuration') ? GitBranch : name.includes('Auth') ? ShieldCheck : name.includes('Duplicate') ? ListChecks : Network
function App(){
  const [page,setPage] = useState('Overview')
  const [dash,setDash] = useState(null), [scenarios,setScenarios] = useState([]), [selected,setSelected] = useState('database_pool')
  const [autoRecovery,setAutoRecovery] = useState(true), [current,setCurrent] = useState(null), [busy,setBusy] = useState(false), [notice,setNotice] = useState('')
  const [users,setUsers] = useState({username:'jaggu', message:''}), [username,setUsername] = useState('jaggu')
  const [filter,setFilter] = useState('')
  async function refresh(){
    try { const [d,s] = await Promise.all([request('/dashboard'),request('/scenarios')]); setDash(d); setScenarios(s)
      if (current?.id) { const updated = await request(`/incidents/${current.id}`).catch(()=>null); if(updated) setCurrent(updated) }
    } catch(e){setNotice('Backend not connected. Start FastAPI on port 8000, then refresh.')}
  }
  useEffect(()=>{ refresh(); const t=setInterval(refresh,5000); return ()=>clearInterval(t) },[current?.id])
  useEffect(()=>{
    const params = new URLSearchParams(window.location.search)
    const incidentId = params.get('incidentId')
    if (!incidentId) return
    request(`/incidents/${encodeURIComponent(incidentId)}`)
      .then(incident => { setCurrent(incident); setPage('Root Cause Analysis'); setNotice(`Opened incident ${incident.id} from ShopSphere.`) })
      .catch(() => setNotice(`Could not load linked incident ${incidentId}. Check that SignalRoot is using the same backend database.`))
  },[])
  async function run(fn, success){
    setBusy(true); setNotice('')
    try { const result=await fn(); if(result?.id) setCurrent(result); await refresh(); setNotice(success || 'Action completed.'); return result }
    catch(e){setNotice(e.message || 'Request failed. Is the backend running?')}
    finally{setBusy(false)}
  }
  const inject = () => run(()=>request('/incidents/inject',{method:'POST',body:JSON.stringify({scenario_id:selected,auto_recovery:autoRecovery,duration_seconds:20})}), 'Fault scenario simulated. Evidence was saved.')
  const act = (action) => current && run(()=>request(`/incidents/${current.id}/${action}`,{method:'POST'}), action==='apply-fix'?'Demo fix applied. Replay to verify it.':'Replay completed.')
  const reset = () => run(()=>request('/lab/reset',{method:'POST'}).then(x=>{setCurrent(null);return x}), 'Lab reset.')
  async function register(e){
    e.preventDefault(); setUsers({...users,message:''})
    try { const r=await request('/playground/register',{method:'POST',body:JSON.stringify({username})}); setUsers({username:r.username,message:r.message}) }
    catch(err){ let msg=err.message; try {const obj=JSON.parse(msg); if(obj.suggestion) msg=`Username already exists. Suggested available username: ${obj.suggestion}`}catch{} setUsers({username,message:msg}) }
  }
  const nav = [
    ['Overview',LayoutDashboard],['Application Playground',Activity],['Fault Injection Lab',FlaskConical],['Service Dependency Map',Network],
    ['Live Services',Network],['Incidents & Evidence',Siren],['Telemetry Explorer',Activity],['Change Events',GitBranch],['Incident Timeline',Clock3],['Root Cause Analysis',Search],['AI Investigation Assistant',CircleHelp],['Diagnostic Tests',ClipboardCheck]
  ]
  const visibleIncidents=(dash?.incidents||[]).filter(i=>`${i.title} ${i.id} ${i.status}`.toLowerCase().includes(filter.toLowerCase()))
  return <div className="app-shell">
    <aside className="sidebar">
      <div className="brand"><div className="brand-icon"><Activity size={21}/></div><div><strong>SignalRoot</strong><small>INCIDENT INTELLIGENCE</small></div></div>
      <div className="workspace"><span className="green-dot"/> LOCAL DEMO ENVIRONMENT <ChevronRight size={14}/></div>
      <div className="nav-label">WORKSPACE</div>
      {nav.map(([label,Icon])=><button key={label} onClick={()=>setPage(label)} className={'nav-item '+(page===label?'active':'')}><Icon size={17}/><span>{label}</span>{label==='Incidents & Evidence'&&dash?.counts?.open>0&&<em>{dash.counts.open}</em>}</button>)}
      <div className="side-bottom"><div className="secure"><ShieldCheck size={17}/><div><b>Safe simulation mode</b><small>No production systems connected</small></div></div><div className="version">SIGNALROOT · PROTOTYPE 1.0</div></div>
    </aside>
    <main className="main">
      <header className="topbar"><div className="crumb">Workspace <ChevronRight size={14}/> <b>{page}</b></div><div className="top-right"><span className="live-pill"><span className="green-dot"/> DEMO ENVIRONMENT</span><button className="icon-btn" title="Refresh" onClick={refresh}><RotateCcw size={16}/></button><div className="avatar">SR</div></div></header>
      <div className="content">
        {notice && <div className={'notice '+(notice.includes('not connected')||notice.includes('Error')?'notice-warn':'')}><CircleHelp size={16}/><span>{notice}</span><button onClick={()=>setNotice('')}><X size={15}/></button></div>}
        {page==='Overview'&&<Overview dash={dash} setPage={setPage} current={current}/>}
        {page==='Application Playground'&&<Playground username={username} setUsername={setUsername} users={users} register={register} run={run}/>}
        {page==='Fault Injection Lab'&&<Lab scenarios={scenarios} selected={selected} setSelected={setSelected} autoRecovery={autoRecovery} setAutoRecovery={setAutoRecovery} inject={inject} busy={busy} current={current} setPage={setPage} reset={reset}/>}
        {page==='Live Services'&&<Services dash={dash}/>}{page==='Service Dependency Map'&&<DependencyMap current={current} setCurrent={setCurrent} setPage={setPage}/>} 
        {page==='Incidents & Evidence'&&<Incidents incidents={visibleIncidents} filter={filter} setFilter={setFilter} setCurrent={setCurrent} setPage={setPage} current={current}/>}
        {page==='Telemetry Explorer'&&<TelemetryExplorer/>}
        {page==='Change Events'&&<ChangeEvents/>}
        {page==='Incident Timeline'&&<IncidentTimeline current={current} setCurrent={setCurrent} setPage={setPage}/>}
        {page==='Root Cause Analysis'&&<Analysis current={current} act={act} busy={busy} setPage={setPage}/>}{page==='AI Investigation Assistant'&&<InvestigationAssistant current={current}/>}{page==='Diagnostic Tests'&&<DiagnosticTests current={current} setCurrent={setCurrent}/>}
      </div>
      <footer><span><span className="green-dot"/> API {dash?'connected':'waiting for backend'}</span><span>Evidence-first incident analysis · Local simulation only</span></footer>
    </main>
  </div>
}
function PageHeading({eyebrow,title,desc,actions}){return <div className="page-heading"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1><p>{desc}</p></div>{actions&&<div className="heading-actions">{actions}</div>}</div>}
function Stat({label,value,sub,Icon,tone='blue'}){return <div className="stat-card"><div className={'stat-icon '+tone}><Icon size={18}/></div><div className="stat-label">{label}</div><div className="stat-value">{value??'—'}</div><div className="stat-sub">{sub}</div></div>}
function Overview({dash,setPage,current}){
 return <><PageHeading eyebrow="SYSTEM OVERVIEW" title="Incident command center" desc="Monitor service health, investigate incidents, and verify fixes in a safe local environment." actions={<button className="btn primary" onClick={()=>setPage('Fault Injection Lab')}><Zap size={16}/> Run a simulation</button>}/>
 <div className="stat-grid"><Stat label="Tracked incidents" value={dash?.counts.total??0} sub="Historical investigations" Icon={Siren}/><Stat label="Open investigations" value={dash?.counts.open??0} sub="Require engineer review" Icon={AlertTriangle} tone="orange"/><Stat label="Recovered incidents" value={dash?.counts.recovered??0} sub="Evidence retained" Icon={Activity} tone="green"/><Stat label="Fixes verified" value={dash?.counts.fixed??0} sub="Recorded engineer fixes" Icon={CheckCircle2} tone="purple"/></div>
 <div className="section-grid"><section className="panel wide"><div className="panel-head"><div><h2>Service health</h2><p>Simulated application dependency map</p></div><button className="text-btn" onClick={()=>setPage('Live Services')}>View all <ArrowRight size={14}/></button></div><ServiceMap services={dash?.services||[]}/></section>
 <section className="panel"><div className="panel-head"><div><h2>Investigation workflow</h2><p>Evidence before conclusions</p></div></div><div className="workflow">{[['01','Detect the symptom','Capture the failing request.'],['02','Correlate evidence','Connect logs, metrics, traces and changes.'],['03','Rank hypotheses','Show evidence and uncertainty.'],['04','Verify a fix','Apply in the lab and replay.']].map(x=><div className="workflow-row" key={x[0]}><span>{x[0]}</span><div><b>{x[1]}</b><small>{x[2]}</small></div><ChevronRight size={15}/></div>)}</div></section></div>
 <section className="panel incidents-panel"><div className="panel-head"><div><h2>Recent incidents</h2><p>Resolved incidents remain available for investigation</p></div><button className="text-btn" onClick={()=>setPage('Incidents & Evidence')}>All incidents <ArrowRight size={14}/></button></div>
 {dash?.incidents?.length ? <IncidentTable incidents={dash.incidents.slice(0,5)} onSelect={i=>{setPage('Root Cause Analysis');}}/>:<Empty icon={Siren} title="No incidents yet" desc="Start a fault simulation to generate real demo evidence." action={<button className="btn primary" onClick={()=>setPage('Fault Injection Lab')}>Open fault lab</button>}/>}</section>
 <div className="bottom-callout"><div className="callout-icon"><ShieldCheck size={20}/></div><div><b>Investigation does not apply fixes automatically</b><p>Root-cause hypotheses are separate from remediation. An engineer reviews the evidence, applies a lab-only fix, and replays the scenario.</p></div></div></>
}
function ServiceMap({services}){
 const edges=[['Web App','API Gateway'],['API Gateway','API Service'],['API Service','Database'],['API Service','Inventory Service'],['API Service','Auth Service'],['API Service','Worker']]
 if(!services.length)return <div className="loading-state"><LoaderCircle className="spin"/> Waiting for service health data…</div>
 return <div className="service-map"><div className="map-nodes">{services.map((s,i)=>{const Icon=s.name==='Database'?Database:s.name==='Worker'?Activity:s.name==='Web App'?LayoutDashboard:s.name==='Auth Service'?ShieldCheck:Network;return <div className={'service-node '+s.status} key={s.name}><div className="node-top"><Icon size={17}/><span className={'health-dot '+s.status}/></div><b>{s.name}</b><small>{s.status==='healthy'?'Operational':s.status==='failed'?'Failure detected':'Degraded'}</small><div className="node-metrics"><span>{s.latency_ms} ms</span><span>{s.error_rate}% errors</span></div></div>})}</div><div className="map-note"><span className="legend-dot healthy"/> Healthy <span className="legend-dot degraded"/> Degraded <span className="legend-dot failed"/> Failed <span className="map-explain">Service status is simulated from lab incidents.</span></div></div>
}
function Lab({scenarios,selected,setSelected,autoRecovery,setAutoRecovery,inject,busy,current,setPage,reset}){
 const chosen=scenarios.find(s=>s.id===selected)
 return <><PageHeading eyebrow="CONTROLLED TEST ENVIRONMENT" title="Fault injection lab" desc="Trigger a safe, reproducible failure in the demo application and inspect the evidence it generates." actions={<button className="btn secondary" onClick={reset}><RotateCcw size={15}/> Reset lab</button>}/>
 <div className="lab-warning"><ShieldCheck size={19}/><div><b>Isolated simulation environment</b><p>These scenarios modify only this prototype's simulated state. No real database, network, user account, or production service is disrupted.</p></div></div>
 <div className="lab-layout"><section className="panel scenario-panel"><div className="panel-head"><div><h2>Choose a failure scenario</h2><p>Select a symptom to reproduce</p></div><span className="tiny-count">{scenarios.length} SCENARIOS</span></div><div className="scenario-list">{scenarios.map(s=>{const Icon=iconFor(s.name);return <button className={'scenario-option '+(selected===s.id?'selected':'')} key={s.id} onClick={()=>setSelected(s.id)}><span className="scenario-icon"><Icon size={18}/></span><span className="scenario-text"><b>{s.name}</b><small>{s.description}</small></span><span className={'severity '+s.severity}>{s.severity}</span>{selected===s.id&&<CheckCircle2 size={16} className="selected-check"/>}</button>})}</div></section>
 <section className="panel inject-panel"><div className="panel-head"><div><h2>Simulation settings</h2><p>Review before triggering</p></div><FlaskConical size={20} className="muted-icon"/></div>{chosen&&<><div className="selected-summary"><div className="summary-icon"><Zap size={21}/></div><div><small>SELECTED SCENARIO</small><h3>{chosen.name}</h3><p>{chosen.description}</p></div></div><div className="setting-row"><div><b>Automatic recovery</b><small>Clear the simulated fault after evidence is captured.</small></div><button className={'toggle '+(autoRecovery?'on':'')} onClick={()=>setAutoRecovery(!autoRecovery)} aria-label="Toggle automatic recovery"><span/></button></div><div className="setting-row"><div><b>Evidence retention</b><small>Keep incident logs, metrics, traces and timeline.</small></div><span className="setting-value"><ShieldCheck size={14}/> Enabled</span></div><div className="scenario-impact"><div><span>Service</span><b>{chosen.service}</b></div><div><span>Severity</span><b className={'sev-text '+chosen.severity}>{chosen.severity.toUpperCase()}</b></div></div><button className="btn primary full" onClick={inject} disabled={busy}><Play size={16}/>{busy?'Running simulation…':'Inject fault'}</button><p className="helper-text"><CircleHelp size={13}/> Auto-recovery restores the simulated service state, not the underlying defect.</p></>}</section></div>
 {current&&<section className="panel current-incident"><div className="panel-head"><div><div className="eyebrow">LATEST SIMULATION</div><h2>{current.title}</h2><p>{current.id} · {current.status}</p></div><span className={'status-pill '+current.status}>{current.status}</span></div><div className="incident-summary-grid"><div><small>Evidence records</small><b>{current.evidence?.length||0}</b></div><div><small>Timeline events</small><b>{current.timeline?.length||0}</b></div><div><small>Leading hypothesis</small><b>{current.hypotheses?.[0]?.cause||'Pending'}</b></div></div><button className="btn primary" onClick={()=>setPage('Root Cause Analysis')}>Investigate incident <ArrowRight size={16}/></button></section>}</>
}
function Playground({username,setUsername,users,register,run}){
 const [data,setData]=useState(null),[err,setErr]=useState('')
 async function load(){setErr('');try{setData(await request('/playground/data'))}catch(e){setErr(e.message)}}
 return <><PageHeading eyebrow="SAMPLE APPLICATION" title="Application playground" desc="A small simulated product website where typical user-facing issues can be reproduced." actions={<button className="btn secondary" onClick={load}><RotateCcw size={15}/> Test data endpoint</button>}/>
 <div className="playground-grid"><section className="panel demo-app"><div className="mock-browser"><div className="browser-dots"><i/><i/><i/></div><span>demo-app.local / workspace</span><ShieldCheck size={15}/></div><div className="demo-welcome"><div className="demo-tag">SAMPLE WEB APPLICATION</div><h2>Welcome to your workspace.</h2><p>Use this sandbox to reproduce common application issues and inspect what the incident platform captures.</p><div className="demo-cards"><div><BarChart3 size={19}/><b>Service reports</b><small>View generated reports</small></div><div><ListChecks size={19}/><b>Background jobs</b><small>Inspect task status</small></div><div><Database size={19}/><b>Data service</b><small>Test backend access</small></div></div><button className="btn primary" onClick={load}><Activity size={16}/> Load application data</button>{err&&<div className="inline-error"><AlertTriangle size={16}/>{err}</div>}{data&&<div className="data-results"><b>Endpoint response</b>{data.items.map(i=><div key={i.id}><span>{i.name}</span><span className="status-text">{i.status}</span></div>)}</div>}</div></section>
 <section className="panel register-panel"><div className="panel-head"><div><h2>Registration test</h2><p>Reproduce a duplicate username conflict</p></div><ShieldCheck size={18} className="muted-icon"/></div><div className="field-label">USERNAME</div><form onSubmit={register}><input value={username} onChange={e=>setUsername(e.target.value)} placeholder="Try jaggu" minLength="2" maxLength="32"/><button className="btn primary full" type="submit">Register demo user <ArrowRight size={15}/></button></form><div className="register-note"><CircleHelp size={15}/><span>Try registering <b>jaggu</b> first (already exists), then use the suggested alternative. This uses a local demo database only.</span></div>{users.message&&<div className={'registration-result '+(users.message.includes('registered')?'success':'error')}><AlertTriangle size={16}/><span>{users.message}</span></div>}</section></div>
 <div className="bottom-callout"><div className="callout-icon"><Zap size={20}/></div><div><b>Turn a user symptom into an investigation</b><p>After reproducing a failure, open the Fault Injection Lab to generate a correlated incident record with timeline and evidence.</p></div></div></>
}
function Services({dash}){return <><PageHeading eyebrow="OBSERVABILITY" title="Live service map" desc="Health, latency, and error-rate signals from the local simulation."/><section className="panel"><div className="panel-head"><div><h2>Service dependency overview</h2><p>Refreshes every five seconds</p></div><span className="live-pill"><span className="green-dot"/> LIVE DEMO</span></div><ServiceMap services={dash?.services||[]}/></section><div className="service-cards">{(dash?.services||[]).map(s=><div className="panel service-detail" key={s.name}><div className="service-detail-head"><b>{s.name}</b><span className={'health-dot '+s.status}/></div><div className="detail-stat"><small>Latency</small><b>{s.latency_ms} ms</b></div><div className="meter"><i style={{width:Math.min(100,s.latency_ms/10)+'%'}}/></div><div className="detail-stat"><small>Error rate</small><b>{s.error_rate}%</b></div><div className="meter"><i style={{width:Math.min(100,s.error_rate*3)+'%'}}/></div></div>)}</div></>}
function Incidents({incidents,filter,setFilter,setCurrent,setPage,current}){return <><PageHeading eyebrow="INVESTIGATION HISTORY" title="Incidents & evidence" desc="Search incident records and open the underlying timeline and evidence."/><section className="panel"><div className="search-bar"><Search size={17}/><input placeholder="Search incident, scenario, or status…" value={filter} onChange={e=>setFilter(e.target.value)}/><span>{incidents.length} records</span></div>{incidents.length?<IncidentTable incidents={incidents} onSelect={async i=>{try{const x=await request(`/incidents/${i.id}`);setCurrent(x);setPage('Root Cause Analysis')}catch{}}}/>:<Empty icon={Search} title="No matching incidents" desc="Try another search, or run a scenario in the fault lab."/>}</section></>}
function IncidentTable({incidents,onSelect}){return <div className="table-wrap"><table><thead><tr><th>INCIDENT</th><th>SEVERITY</th><th>STATUS</th><th>EVIDENCE</th><th>CREATED</th><th></th></tr></thead><tbody>{incidents.map(i=><tr key={i.id} onClick={()=>onSelect(i)}><td><b>{i.title}</b><small>{i.id}</small></td><td><span className={'severity '+i.severity}>{i.severity}</span></td><td><span className={'status-pill '+i.status}>{i.status}</span></td><td>{i.evidence?.length||0} records</td><td>{new Date(i.created_at).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})}</td><td><ChevronRight size={16}/></td></tr>)}</tbody></table></div>}

function TelemetryExplorer(){
 const [items,setItems]=useState([]),[message,setMessage]=useState(''),[service,setService]=useState('API Service'),[kind,setKind]=useState('log'),[severity,setSeverity]=useState('warning'),[textValue,setTextValue]=useState('Request latency increased above threshold'),[busy,setBusy]=useState(false)
 async function load(){try{setItems(await request('/telemetry?limit=100'))}catch(e){setMessage(e.message)}}
 useEffect(()=>{load()},[])
 async function submit(e){e.preventDefault();setBusy(true);setMessage('');try{await request('/telemetry/ingest',{method:'POST',body:JSON.stringify({source:'manual-demo',signal_type:kind,service_name:service,severity,message:textValue,attributes:{environment:'local-demo'}})});setMessage('Telemetry record accepted and stored.');await load()}catch(e){setMessage(e.message)}finally{setBusy(false)}}
 return <><PageHeading eyebrow="OBSERVABILITY DATA" title="Telemetry explorer" desc="Inspect stored signals and ingest a sample structured event. This endpoint is for local demo telemetry only."/><div className="telemetry-layout"><section className="panel"><div className="panel-head"><div><h2>Ingest telemetry</h2><p>Logs · metrics · traces · changes</p></div><Activity size={18} className="muted-icon"/></div><form className="telemetry-form" onSubmit={submit}><label>Service name<select value={service} onChange={e=>setService(e.target.value)}>{['Web App','API Gateway','API Service','Database','Inventory Service','Worker','Auth Service'].map(x=><option key={x}>{x}</option>)}</select></label><div className="telemetry-fields"><label>Signal type<select value={kind} onChange={e=>setKind(e.target.value)}>{['log','metric','trace','change','event'].map(x=><option key={x}>{x}</option>)}</select></label><label>Severity<select value={severity} onChange={e=>setSeverity(e.target.value)}>{['debug','info','warning','error','critical'].map(x=><option key={x}>{x}</option>)}</select></label></div><label>Message<textarea value={textValue} onChange={e=>setTextValue(e.target.value)} rows="3" required maxLength="4000"/></label><button className="btn primary full" disabled={busy}><Zap size={15}/>{busy?'Ingesting…':'Ingest demo telemetry'}</button>{message&&<p className="telemetry-message">{message}</p>}</form></section><section className="panel"><div className="panel-head"><div><h2>Stored telemetry</h2><p>Newest 100 records</p></div><button className="text-btn" onClick={load}><RotateCcw size={14}/> Refresh</button></div>{items.length?<div className="telemetry-list">{items.map(x=><div key={x.id}><div className="telemetry-row-top"><span className={'evidence-type '+x.severity}>{x.signal_type} / {x.severity}</span><code>{x.id}</code></div><b>{x.message}</b><small>{x.service_name} · {new Date(x.received_at).toLocaleString()}</small></div>)}</div>:<Empty icon={Activity} title="No telemetry ingested" desc="Submit a sample record to start exploring stored signals."/>}</section></div></>
}
function ChangeEvents(){
 const [items,setItems]=useState([]),[service,setService]=useState('Inventory Service'),[type,setType]=useState('deployment'),[version,setVersion]=useState('v2.4.1'),[summary,setSummary]=useState('Reduced database connection pool limit'),[actor,setActor]=useState('demo-engineer'),[notice,setNotice]=useState(''),[busy,setBusy]=useState(false),[traceResult,setTraceResult]=useState(null),[failService,setFailService]=useState('Inventory Service')
 async function load(){try{setItems(await request('/changes?limit=100'))}catch(e){setNotice(e.message)}}
 useEffect(()=>{load()},[])
 async function submit(e){e.preventDefault();setBusy(true);setNotice('');try{await request('/changes',{method:'POST',body:JSON.stringify({service_name:service,change_type:type,version,summary,actor})});setNotice('Change event recorded. Investigators can correlate it with nearby incidents.');await load()}catch(e){setNotice(e.message)}finally{setBusy(false)}}
 async function runTrace(){setBusy(true);setNotice('');try{const r=await request(`/demo/distributed-request${failService?'?fail_service='+encodeURIComponent(failService):''}`,{method:'POST'});setTraceResult(r);setNotice(`Distributed trace generated: ${r.trace_id}`)}catch(e){setNotice(e.message)}finally{setBusy(false)}}
 return <><PageHeading eyebrow="CHANGE-AWARE INVESTIGATION" title="Deployments & change events" desc="Record releases and configuration changes, then compare their timing with incidents. A nearby change is a lead—not proof of causation."/><div className="telemetry-layout"><section className="panel"><div className="panel-head"><div><h2>Record a change</h2><p>Deployment · configuration · feature flag · rollback</p></div><Wrench size={18} className="muted-icon"/></div><form className="telemetry-form" onSubmit={submit}><label>Service<select value={service} onChange={e=>setService(e.target.value)}>{['Web App','API Gateway','API Service','Database','Inventory Service','Worker','Auth Service'].map(x=><option key={x}>{x}</option>)}</select></label><div className="telemetry-fields"><label>Change type<select value={type} onChange={e=>setType(e.target.value)}>{['deployment','configuration','feature_flag','rollback','dependency'].map(x=><option key={x}>{x}</option>)}</select></label><label>Version / change ID<input value={version} onChange={e=>setVersion(e.target.value)} required maxLength="120"/></label></div><label>Summary<textarea value={summary} onChange={e=>setSummary(e.target.value)} rows="3" required maxLength="2000"/></label><label>Actor<input value={actor} onChange={e=>setActor(e.target.value)} maxLength="120"/></label><button className="btn primary full" disabled={busy}><Wrench size={15}/>{busy?'Saving…':'Record change event'}</button></form><div className="divider-line"/><div className="panel-head"><div><h2>Generate distributed trace</h2><p>Creates a local multi-service span chain with shared trace context</p></div><GitBranch size={18} className="muted-icon"/></div><label className="telemetry-form">Simulated failing service<select value={failService} onChange={e=>setFailService(e.target.value)}>{['Inventory Service','API Gateway','Database',''].map(x=><option key={x} value={x}>{x||'No failure'}</option>)}</select><button className="btn secondary full" onClick={runTrace} disabled={busy}><Activity size={15}/>{busy?'Generating…':'Run distributed trace demo'}</button></label>{traceResult&&<div className="analysis-explanation"><b>Trace generated</b><p>Trace ID: {traceResult.trace_id}</p><small>{traceResult.services.join(' → ')}{traceResult.failed_service?` · simulated failure: ${traceResult.failed_service}`:''}</small></div>}</section><section className="panel"><div className="panel-head"><div><h2>Recorded change history</h2><p>Newest 100 changes</p></div><button className="text-btn" onClick={load}><RotateCcw size={14}/> Refresh</button></div>{items.length?<div className="recurrence-list">{items.map(x=><div key={x.id}><span><b>{x.summary}</b><small>{x.service_name} · {x.change_type} · {x.version} · {new Date(x.occurred_at).toLocaleString()}</small></span><span className="tiny-count">{x.id}</span></div>)}</div>:<Empty icon={GitBranch} title="No changes recorded" desc="Record a demo deployment or configuration change to begin building change history."/>}</section></div>{notice&&<div className="notice"><CircleHelp size={16}/><span>{notice}</span><button onClick={()=>setNotice('')}><X size={15}/></button></div>}</>
}

function IncidentTimeline({current,setCurrent,setPage}){
 const [incidents,setIncidents]=useState([]),[selected,setSelected]=useState(current?.id||''),[data,setData]=useState(null),[impact,setImpact]=useState(null),[loading,setLoading]=useState(false),[error,setError]=useState('')
 useEffect(()=>{request('/incidents').then(items=>{setIncidents(items);if(current?.id)setSelected(current.id);else if(items.length)setSelected(items[0].id)}).catch(e=>setError(e.message))},[current?.id])
 useEffect(()=>{if(!selected){setData(null);return}setLoading(true);setError('');request(`/incidents/${selected}/timeline`).then(setData).catch(e=>setError(e.message)).finally(()=>setLoading(false))},[selected])
 const kindTone=(kind)=>kind==='change'?'change':kind==='verification'?'verify':kind==='remediation'?'fix':kind==='incident'?'incident':kind==='trace'?'trace':kind==='metric'?'metric':'evidence'
 return <><PageHeading eyebrow="CHRONOLOGICAL EVIDENCE" title="Incident timeline" desc="View incident events, telemetry, changes, and verification outcomes on one ordered timeline. Ordering helps investigation; it does not establish causation." actions={<button className="btn secondary" onClick={()=>selected&&request(`/incidents/${selected}/timeline`).then(setData).catch(e=>setError(e.message))}><RotateCcw size={15}/> Refresh timeline</button>}/>
 <section className="panel timeline-toolbar"><label>Select incident<select value={selected} onChange={e=>{setSelected(e.target.value);const found=incidents.find(i=>i.id===e.target.value);if(found)setCurrent(found)}}><option value="">Choose an incident</option>{incidents.map(i=><option key={i.id} value={i.id}>{i.id} · {i.title}</option>)}</select></label><div className="timeline-stats"><div><small>Events</small><b>{data?.counts?.total??'—'}</b></div><div><small>Telemetry</small><b>{data?.counts?.telemetry??'—'}</b></div><div><small>Changes</small><b>{data?.counts?.changes??'—'}</b></div><div><small>Verification</small><b>{data?.counts?.verification??'—'}</b></div></div></section>
 {error&&<div className="notice notice-warn"><AlertTriangle size={16}/><span>{error}</span></div>}{loading&&<section className="panel"><p>Loading chronological evidence…</p></section>}
 {!loading&&data&&<><section className="panel timeline-panel"><div className="panel-head"><div><h2>{data.title}</h2><p>{data.incident_id} · affected service: {data.service} · chronological order</p></div><span className="tiny-count">{data.events.length} EVENTS</span></div>{data.events.length?<div className="event-timeline">{data.events.map((e,i)=><div className="event-row" key={`${e.evidence_id||'event'}-${i}`}><div className="event-rail"><span className={'event-dot '+kindTone(e.kind)}></span>{i<data.events.length-1&&<i/>}</div><div className="event-card"><div className="event-card-top"><span className={'event-type '+kindTone(e.kind)}>{e.kind}</span><time>{e.timestamp?new Date(e.timestamp).toLocaleString():'Timestamp unavailable'}</time></div><b>{e.title}</b><p>{e.detail}</p><div className="event-card-meta"><span>{e.source}</span><span>{e.confidence}</span>{e.trace_id&&<span>Trace: {e.trace_id.slice(0,18)}…</span>}{e.evidence_id&&<span>ID: {e.evidence_id}</span>}</div></div></div>)}</div>:<Empty icon={Clock3} title="No timeline events" desc="This incident has no recorded timeline data yet."/>}</section><section className="panel timeline-interpretation"><div className="panel-head"><div><h2>How to interpret this timeline</h2><p>Keep facts separate from causal hypotheses</p></div><ShieldCheck size={18} className="muted-icon"/></div>{data.interpretation.map((line,i)=><p key={i}><CheckCircle2 size={15}/>{line}</p>)}<button className="btn primary" onClick={()=>setPage('Root Cause Analysis')}><Search size={15}/> Continue root cause analysis</button></section></>}
 {!loading&&!data&&!error&&<Empty icon={Clock3} title="Select an incident" desc="Choose an incident to combine its recorded timeline with correlated telemetry, nearby changes, and verification events."/>}</>
}

function Analysis({current,act,busy,setPage}){const [analysis,setAnalysis]=useState(null); const [recurrence,setRecurrence]=useState(null); const [correlation,setCorrelation]=useState(null); useEffect(()=>{if(current?.id){request(`/incidents/${current.id}/analysis`).then(setAnalysis).catch(()=>setAnalysis(null));request(`/incidents/${current.id}/recurrence`).then(setRecurrence).catch(()=>setRecurrence(null));request(`/incidents/${current.id}/correlation`).then(setCorrelation).catch(()=>setCorrelation(null))}else{setAnalysis(null);setRecurrence(null);setCorrelation(null)}},[current?.id,current?.evidence?.length]); if(!current)return <><PageHeading eyebrow="EVIDENCE-BASED DIAGNOSIS" title="Root cause analysis" desc="Select an incident from the incident history or generate one in the fault lab."/><Empty icon={Search} title="No incident selected" desc="Run a fault simulation, then return here to investigate the captured evidence." action={<button className="btn primary" onClick={()=>setPage('Fault Injection Lab')}>Open fault lab</button>}/></>
 return <><PageHeading eyebrow="INVESTIGATION WORKSPACE" title="Root cause analysis" desc="Review ranked hypotheses, supporting evidence, and the incident timeline." actions={<span className={'status-pill '+current.status}>{current.status}</span>}/><div className="analysis-banner"><div className="analysis-banner-icon"><Siren size={20}/></div><div><small>{current.id} · {current.service} · {current.severity.toUpperCase()} SEVERITY</small><h2>{current.title}</h2><p>{current.symptom}</p></div></div>
 <div className="analysis-grid"><section className="panel"><div className="panel-head"><div><h2>Ranked hypotheses</h2><p>Candidate causes, not unquestionable facts</p></div><span className="tiny-count">SIGNAL-BASED</span></div>{analysis?.explanation&&<div className="analysis-explanation"><b>Evidence-based summary</b><p>{analysis.explanation.summary}</p><small>{analysis.method}</small></div>}<div className="hypotheses">{(analysis?.ranked_hypotheses?.length ? analysis.ranked_hypotheses.map(h=>({...h,confidence:h.score,explanation:`${h.confidence_label}. Matched signals: ${h.matched_signals.join(', ')||'none'}.`,evidence_ids:current.evidence?.filter(e=>h.matched_signals?.some(k=>e.message.toLowerCase().includes(k))).map(e=>e.id)||[]})) : current.hypotheses||[]).map(h=><div className={'hypothesis '+(h.rank===1?'leading':'')} key={h.rank}><div className="rank">{String(h.rank).padStart(2,'0')}</div><div className="hypothesis-body"><div className="hypothesis-title"><b>{h.cause}</b><span>{Math.round(h.confidence*100)}% match</span></div><div className="confidence-track"><i style={{width:(h.confidence*100)+'%'}}/></div><p>{h.explanation}</p><div className="evidence-links">{h.evidence_ids?.length?h.evidence_ids.map(id=><span key={id}><GitBranch size={12}/>{id}</span>):<span>No linked evidence</span>}</div></div></div>)}</div><div className="uncertainty-note"><CircleHelp size={16}/><span>Scores are transparent demo heuristics, not calibrated probabilities. Shared trace IDs are stronger correlation evidence than matching timestamps; verify raw signals before applying a fix.</span></div></section>
 <section className="panel"><div className="panel-head"><div><h2>Recommended correction</h2><p>Engineer-controlled remediation</p></div><Wrench size={18} className="muted-icon"/></div><div className="fix-card"><div className="fix-icon"><Wrench size={20}/></div><div><small>PROPOSED FIX</small><p>{current.recommended_fix}</p></div></div><div className="fix-safety"><ShieldCheck size={15}/> This action changes only the demo incident state.</div><button className="btn primary full" disabled={busy||current.fixed} onClick={()=>act('apply-fix')}><Wrench size={15}/>{current.fixed?'Demo fix applied':'Apply demo fix'}</button><button className="btn secondary full replay-btn" disabled={busy} onClick={()=>act('replay')}><RotateCcw size={15}/> Replay original scenario</button>{current.replay_passed!==null&&current.replay_passed!==undefined&&<div className={'replay-result '+(current.replay_passed?'success':'error')}>{current.replay_passed?<CheckCircle2 size={17}/>:<AlertTriangle size={17}/>} {current.replay_passed?'Replay passed: symptom not reproduced.':'Replay failed: original symptom reproduced.'}</div>}</section></div>
 <section className="panel recurrence-panel"><div className="panel-head"><div><h2>Cross-service telemetry correlation</h2><p>Signals linked by trace ID, incident time window, and affected service</p></div><Network size={18} className="muted-icon"/></div><div className="incident-summary-grid"><div><small>Correlated records</small><b>{correlation?.correlated_count ?? '—'}</b></div><div><small>Trace groups</small><b>{correlation?.trace_group_count ?? '—'}</b></div><div><small>Window</small><b>{correlation?.window_minutes ? `${correlation.window_minutes} min` : '—'}</b></div></div>{correlation?.trace_groups?.length?<div className="recurrence-list">{correlation.trace_groups.map(g=><div key={g.trace_id}><span><b>Trace {g.trace_id.slice(0,16)}…</b><small>{g.services.join(' → ')} · {g.record_count} records · {g.errors} errors</small></span><span className="tiny-count">TRACE</span></div>)}</div>:<div className="recurrence-empty">No trace groups correlated yet. Send OTLP telemetry with shared trace IDs, or ingest error signals near the incident time. Temporal matches are weaker than shared-trace matches.</div>}{correlation?.correlated_telemetry?.length>0&&<div className="telemetry-list">{correlation.correlated_telemetry.slice(0,8).map(r=><div key={r.id}><div className="telemetry-row-top"><span className={'evidence-type '+r.severity}>{r.signal_type} / {r.severity}</span><code>{r.correlation_reason}</code></div><b>{r.message}</b><small>{r.service_name} · {new Date(r.received_at).toLocaleString()}</small></div>)}</div>}{correlation?.related_changes?.length>0&&<><div className="panel-head change-head"><div><h3>Changes preceding the incident</h3><p>Temporally related changes on the affected service or within the incident window</p></div><Wrench size={17} className="muted-icon"/></div><div className="recurrence-list">{correlation.related_changes.map(change=><div key={change.id}><span><b>{change.summary}</b><small>{change.service_name} · {change.change_type} · {change.version} · {new Date(change.occurred_at).toLocaleString()}</small></span><span className="tiny-count">{change.minutes_before_incident===null?'TIME MATCH':`${change.minutes_before_incident} min before`}</span></div>)}</div></>}{correlation?.limitations?.map(x=><p className="muted-note" key={x}>{x}</p>)}</section>
 <section className="panel recurrence-panel"><div className="panel-head"><div><h2>Recurring incident comparison</h2><p>Earlier incidents ranked by scenario and symptom similarity</p></div><RotateCcw size={18} className="muted-icon"/></div>{recurrence?.related_incidents?.length?<div className="recurrence-list">{recurrence.related_incidents.map(item=><div key={item.id}><span><b>{item.title}</b><small>{item.id} · {new Date(item.created_at).toLocaleString()} · {item.match_reason||'related'} · {Math.round((item.similarity||0)*100)}% text similarity</small></span><span className={'status-pill '+item.status}>{item.status}</span></div>)}</div>:<div className="recurrence-empty">No earlier incidents of this scenario type yet. Replay the same scenario again to start comparing recurrence.</div>}</section>
 <section className="panel timeline-panel"><div className="panel-head"><div><h2>Incident timeline</h2><p>Chronological sequence of observed and simulated events</p></div><Clock3 size={18} className="muted-icon"/></div><div className="timeline">{[...(current.timeline||[]),...(current.fix_history||[])].sort((a,b)=>a.timestamp.localeCompare(b.timestamp)).map((e,i)=><div className="timeline-event" key={i}><span className="timeline-dot"/><div><small>{new Date(e.timestamp).toLocaleString()}</small><b>{e.event}</b><p>{e.detail}</p></div></div>)}</div></section>
 <section className="panel evidence-panel"><div className="panel-head"><div><h2>Evidence explorer</h2><p>Inspect the data supporting the investigation</p></div><span className="tiny-count">{current.evidence?.length||0} RECORDS</span></div><div className="evidence-list">{current.evidence?.map(e=><div className="evidence-row" key={e.id}><div className={'evidence-kind '+e.kind}>{e.kind==='metric'?<BarChart3 size={16}/>:e.kind==='trace'?<GitBranch size={16}/>:e.kind==='change'?<Wrench size={16}/>:<ListChecks size={16}/>}</div><div className="evidence-main"><div><b>{e.message}</b><small>{e.source} · {e.request_id}</small></div><span className={'evidence-type '+e.level}>{e.kind} / {e.level}</span></div><code>{e.id}</code></div>)}</div></section></>}
function InvestigationAssistant({current}){
 const [incidents,setIncidents]=useState([]),[incidentId,setIncidentId]=useState(current?.id||''),[question,setQuestion]=useState('What is the leading hypothesis, which evidence supports it, and what should I test next?'),[answer,setAnswer]=useState(null),[busy,setBusy]=useState(false),[error,setError]=useState('')
 useEffect(()=>{request('/incidents').then(items=>{setIncidents(items);if(current?.id)setIncidentId(current.id);else if(items.length)setIncidentId(items[0].id)}).catch(e=>setError(e.message))},[current?.id])
 async function ask(e){e.preventDefault();if(!incidentId)return;setBusy(true);setError('');setAnswer(null);try{setAnswer(await request('/assistant/investigate',{method:'POST',body:JSON.stringify({incident_id:incidentId,question})}))}catch(e){setError(e.message)}finally{setBusy(false)}}
 return <><PageHeading eyebrow="EVIDENCE-GROUNDED AI SUPPORT" title="AI investigation assistant" desc="Ask a question about an incident. When local Ollama is available, it answers using that incident's evidence; otherwise, a deterministic evidence summary is shown."/><div className="assistant-layout"><section className="panel"><div className="panel-head"><div><h2>Ask about an incident</h2><p>Incident data and correlated signals are supplied as context</p></div><CircleHelp size={18} className="muted-icon"/></div><form className="telemetry-form" onSubmit={ask}><label>Incident<select value={incidentId} onChange={e=>{setIncidentId(e.target.value);setAnswer(null)}} required><option value="" disabled>Select an incident</option>{incidents.map(i=><option key={i.id} value={i.id}>{i.id} · {i.title} ({i.status})</option>)}</select></label><label>Your question<textarea value={question} onChange={e=>setQuestion(e.target.value)} rows="4" minLength="3" maxLength="2000" required/></label><button className="btn primary full" disabled={busy||!incidentId}><CircleHelp size={15}/>{busy?'Investigating…':'Investigate with evidence'}</button>{error&&<p className="assistant-error">{error}</p>}</form><div className="assistant-safety"><ShieldCheck size={16}/><span>Read-only assistant. It cannot deploy, modify configuration, or apply fixes. Verify findings against the source records.</span></div></section><section className="panel"><div className="panel-head"><div><h2>Investigation response</h2><p>Facts, hypotheses, unknowns, and next tests</p></div>{answer&&<span className="tiny-count">{answer.mode==='ollama'?'LOCAL OLLAMA':'EVIDENCE FALLBACK'}</span>}</div>{answer?<div className="assistant-answer"><div className="assistant-meta"><span>{answer.mode==='ollama'?`Model: ${answer.model}`:'Deterministic evidence summary'}</span><span>{answer.evidence_counts?.telemetry??0} telemetry · {answer.evidence_counts?.changes??0} changes</span></div><pre>{answer.answer}</pre>{answer.limitations?.map((x,i)=><p className="muted-note" key={i}>{x}</p>)}</div>:<Empty icon={CircleHelp} title="No investigation response yet" desc="Choose an incident and ask a specific question about its symptoms, evidence, likely cause, or next diagnostic tests."/>}</section></div><section className="panel assistant-guidance"><div className="panel-head"><div><h2>Example questions</h2><p>Use concrete questions tied to the incident evidence</p></div></div><div className="assistant-examples">{['Which observations are facts and which are hypotheses?','What evidence would distinguish the top two root-cause candidates?','Could a nearby deployment be related, and what would prove or disprove that?','What regression test should I run before marking the fix verified?'].map(q=><button key={q} type="button" className="assistant-example" onClick={()=>setQuestion(q)}>{q}<ArrowRight size={14}/></button>)}</div></section></>
}


function DependencyMap({current,setCurrent,setPage}){
 const [incidents,setIncidents]=useState([]),[selected,setSelected]=useState(current?.id||''),[data,setData]=useState(null),[impact,setImpact]=useState(null),[loading,setLoading]=useState(false),[error,setError]=useState('')
 useEffect(()=>{request('/incidents').then(items=>{setIncidents(items);if(current?.id)setSelected(current.id);else if(items.length)setSelected(items[0].id)}).catch(e=>setError(e.message))},[current?.id])
 useEffect(()=>{setLoading(true);setError('');const suffix=selected?`?incident_id=${encodeURIComponent(selected)}`:'';Promise.all([request(`/dependencies${suffix}`),request(`/impact${suffix}`)]).then(([d,i])=>{setData(d);setImpact(i)}).catch(e=>setError(e.message)).finally(()=>setLoading(false))},[selected])
 const observed=data?.edges?.filter(e=>e.kind==='observed')||[]
 const configured=data?.edges?.filter(e=>e.kind==='configured')||[]
 return <><PageHeading eyebrow="SERVICE RELATIONSHIPS & FAILURE PROPAGATION" title="Service dependency map" desc="Compare the documented demo topology with cross-service relationships observed in stored spans. An earlier error is a lead, not proof of root cause." actions={<button className="btn secondary" onClick={()=>request(`/dependencies${selected?`?incident_id=${encodeURIComponent(selected)}`:''}`).then(setData).catch(e=>setError(e.message))}><RotateCcw size={15}/> Refresh map</button>}/>
 <section className="panel timeline-toolbar"><label>Scope to incident<select value={selected} onChange={e=>{setSelected(e.target.value);const found=incidents.find(i=>i.id===e.target.value);if(found)setCurrent(found)}}><option value="">All stored telemetry</option>{incidents.map(i=><option key={i.id} value={i.id}>{i.id} · {i.title}</option>)}</select></label><div className="timeline-stats"><div><small>Services</small><b>{data?.nodes?.length??'—'}</b></div><div><small>Configured edges</small><b>{data?.configured_edge_count??'—'}</b></div><div><small>Observed edges</small><b>{data?.observed_edge_count??'—'}</b></div><div><small>Error signals</small><b>{data?.error_count??'—'}</b></div></div></section>
 {error&&<div className="notice notice-warn"><AlertTriangle size={16}/><span>{error}</span></div>}{loading&&<section className="panel"><p>Building dependency view…</p></section>}
 {!loading&&data&&<><section className="panel blast-radius-panel"><div className="panel-head"><div><h2>Estimated blast radius</h2><p>Potential upstream services and user-facing paths affected by the selected failing dependency</p></div><span className={'diagnostic-status '+(impact?.impact_level==='high'?'failed':impact?.impact_level==='medium'?'review':'passed')}>{impact?.impact_level||'unknown'} impact</span></div>{impact?.failing_service?<><div className="diagnostic-summary"><div><b>{impact.estimated_impacted_services?.length||0}</b><small>potentially impacted services</small></div><div><b>{impact.user_facing_functions?.length||0}</b><small>user-facing paths</small></div><div><b>{impact.telemetry_summary?.errors_in_scope??0}</b><small>observed errors in scope</small></div><div><b>{impact.telemetry_summary?.observed_dependency_links??0}</b><small>observed links</small></div></div><p className="muted-note">Failing service: <b>{impact.failing_service}</b></p><div className="dependency-edge-list">{impact.estimated_impacted_services?.length?impact.estimated_impacted_services.map((x,i)=><div className="dependency-edge" key={x.service}><div className="edge-arrow">{i+1}</div><div className="edge-main"><b>{x.service}</b><small>Dependency depth {x.dependency_path_depth} · {x.relationship_basis}</small></div></div>):<p>No upstream dependents were found in the current graph.</p>}</div>{impact.evidence?.map((x,i)=><p className="muted-note" key={i}>{x}</p>)}{impact.limitations?.map((x,i)=><p className="muted-note" key={'lim'+i}>{x}</p>)}</>:<p className="muted-note">No failing service is available. Generate an incident or ingest error telemetry to estimate impact.</p>}</section><section className="panel dependency-panel"><div className="panel-head"><div><h2>Dependency relationships</h2><p>Arrows represent caller → dependency direction where observed, or the documented demo topology</p></div><Network size={18} className="muted-icon"/></div><div className="dependency-legend"><span><i className="dep-dot configured"/> Configured demo relationship</span><span><i className="dep-dot observed"/> Observed span relationship</span><span><i className="dep-dot error"/> Error telemetry observed</span></div><div className="dependency-nodes">{data.nodes.map(n=><div className={'dependency-node '+(n.error_count?'has-error':'')} key={n.id}><div className="dep-node-head"><Network size={17}/><span className={'health-dot '+(n.error_count?'failed':n.telemetry_records?'healthy':'degraded')}/></div><b>{n.name}</b><small>{n.status==='error-observed'?'Error observed':n.status==='telemetry-observed'?'Telemetry observed':'Topology only'}</small><div className="dep-node-stats"><span>{n.telemetry_records} signals</span><span>{n.error_count} errors</span></div>{n.first_error&&<small className="dep-first-error">First recorded error: {new Date(n.first_error).toLocaleTimeString()}</small>}</div>)}</div><div className="dependency-edge-list"><h3>Edges and evidence</h3>{data.edges.map((e,i)=><div className="dependency-edge" key={`${e.source}-${e.target}-${e.kind}-${i}`}><div className={'edge-arrow '+e.kind}>→</div><div className="edge-main"><b>{e.source} <span>→</span> {e.target}</b><small>{e.label} · {e.evidence}</small></div><div className="edge-counts">{e.kind==='observed'?`${e.trace_count} traces · ${e.span_count} spans · ${e.error_count} errors`:'CONFIGURED'}</div></div>)}</div></section>
 <div className="section-grid"><section className="panel"><div className="panel-head"><div><h2>Failure propagation leads</h2><p>Errors ordered by recorded timestamp</p></div><AlertTriangle size={18} className="muted-icon"/></div>{data.propagation_leads?.length?<div className="propagation-list">{data.propagation_leads.map(x=><div className="propagation-step" key={`${x.step}-${x.timestamp}-${x.service}`}><span>{x.step}</span><div><b>{x.service}</b><small>{x.timestamp?new Date(x.timestamp).toLocaleString():'Time unavailable'}</small><p>{x.message}</p><small>{x.interpretation}</small></div></div>)}</div>:<Empty icon={Activity} title="No error signals found" desc="Generate a failing distributed trace or ingest error telemetry to explore failure propagation."/>}</section><section className="panel"><div className="panel-head"><div><h2>Related changes</h2><p>Change events in the selected incident scope</p></div><GitBranch size={18} className="muted-icon"/></div>{data.related_changes?.length?<div className="recurrence-list">{data.related_changes.map(c=><div key={c.id}><span><b>{c.summary}</b><small>{c.service_name} · {c.change_type} · {new Date(c.occurred_at).toLocaleString()}</small></span></div>)}</div>:<Empty icon={GitBranch} title="No related changes" desc="Record a change event and scope the map to an incident to review temporal leads."/>}</section></div>
 <section className="panel timeline-interpretation"><div className="panel-head"><div><h2>Interpretation safeguards</h2><p>What this map can and cannot conclude</p></div><ShieldCheck size={18} className="muted-icon"/></div>{data.limitations.map((x,i)=><p key={i}><CheckCircle2 size={15}/>{x}</p>)}<button className="btn primary" onClick={()=>setPage('Incident Timeline')}><Clock3 size={15}/> Open incident timeline</button></section></>}
 {!loading&&!data&&!error&&<Empty icon={Network} title="No dependency data" desc="Start the backend and generate a distributed trace or incident telemetry."/>}</>
}

function Empty({icon:Icon,title,desc,action}){return <div className="empty-state"><div className="empty-icon"><Icon size={23}/></div><h3>{title}</h3><p>{desc}</p>{action}</div>}
createRoot(document.getElementById('root')).render(<App/>)


function DiagnosticTests({current,setCurrent}){
 const [incidents,setIncidents]=useState([]), [selected,setSelected]=useState(current?.id||''), [data,setData]=useState(null), [runResult,setRunResult]=useState(null), [loading,setLoading]=useState(false), [error,setError]=useState(''), [httpResult,setHttpResult]=useState(null), [httpBusy,setHttpBusy]=useState(false), [httpError,setHttpError]=useState(''), [baselineResult,setBaselineResult]=useState(null), [compareResult,setCompareResult]=useState(null), [compareBusy,setCompareBusy]=useState(false), [compareError,setCompareError]=useState(''), [incidentReport,setIncidentReport]=useState(null), [incidentVerifyBusy,setIncidentVerifyBusy]=useState(false), [incidentVerifyError,setIncidentVerifyError]=useState('')
 useEffect(()=>{request('/incidents').then(items=>{setIncidents(items); if(current?.id){setSelected(current.id)}else if(items.length){setSelected(items[0].id)}}).catch(e=>setError(e.message))},[current?.id])
 useEffect(()=>{if(!selected){setData(null);return} setLoading(true);setError('');setRunResult(null);request(`/incidents/${selected}/diagnostic-tests`).then(setData).catch(e=>setError(e.message)).finally(()=>setLoading(false))},[selected])
 async function execute(){if(!selected)return;setLoading(true);setError('');try{const r=await request(`/incidents/${selected}/run-diagnostics`,{method:'POST'});setRunResult(r);const updated=await request(`/incidents/${selected}`).catch(()=>null);if(updated)setCurrent(updated);const d=await request(`/incidents/${selected}/diagnostic-tests`);setData(d)}catch(e){setError(e.message)}finally{setLoading(false)}}
 const latest=runResult || data?.latest_runs?.[0]
 return <><PageHeading eyebrow="SAFE VALIDATION WORKFLOW" title="Diagnostic tests" desc="Generate targeted checks from an incident, run rule-based validations against recorded demo evidence, and track replay verification." actions={<button className="btn primary" disabled={!selected||loading} onClick={execute}><Play size={15}/>{loading?'Running checks…':'Run diagnostic checks'}</button>}/>
 <div className="lab-warning"><ShieldCheck size={19}/><div><b>Simulation-only test runner</b><p>These checks inspect saved incident evidence and the demo fix/replay state. They do not execute arbitrary code, call production services, or prove real-world causality.</p></div></div>
 <div className="diagnostic-layout"><section className="panel diagnostic-select"><div className="panel-head"><div><h2>Select an incident</h2><p>Test cases are tailored to the incident scenario</p></div></div><label>Incident<select value={selected} onChange={e=>setSelected(e.target.value)}><option value="">Choose an incident…</option>{incidents.map(i=><option key={i.id} value={i.id}>{i.id} · {i.title}</option>)}</select></label>{selected&&<div className="diagnostic-incident"><small>SELECTED INCIDENT</small><b>{incidents.find(i=>i.id===selected)?.title||selected}</b><span>{incidents.find(i=>i.id===selected)?.status||'status unavailable'}</span></div>}{error&&<p className="assistant-error">{error}</p>}</section>
 <section className="panel"><div className="panel-head"><div><h2>Generated test plan</h2><p>{data?.tests?.length||0} targeted checks · deterministic rules</p></div><ClipboardCheck size={20} className="muted-icon"/></div>{!selected?<div className="recurrence-empty">Generate an incident in Fault Injection Lab to create a diagnostic plan.</div>:loading&&!data?<div className="loading-state"><LoaderCircle className="spin"/> Loading diagnostic plan…</div>:<div className="diagnostic-list">{(data?.tests||[]).map((t,i)=><div className="diagnostic-case" key={t.id}><span className="diagnostic-number">{String(i+1).padStart(2,'0')}</span><div><b>{t.name}</b><p>{t.purpose}</p><small>{t.kind.replace('_',' ')}</small></div></div>)}</div>}</section></div>
 {latest&&<section className="panel diagnostic-results"><div className="panel-head"><div><h2>Latest verification run</h2><p>{latest.id} · {new Date(latest.created_at).toLocaleString()}</p></div><span className={'diagnostic-status '+(latest.overall==='passed'?'passed':latest.overall==='failed'?'failed':'review')}>{latest.overall}</span></div><div className="diagnostic-summary">{Object.entries(latest.summary||{}).map(([k,v])=><div key={k}><b>{v}</b><small>{k}</small></div>)}</div><div className="diagnostic-list">{(latest.results||[]).map(r=><div className="diagnostic-case" key={r.id}><span className={'diagnostic-result '+r.status}>{r.status==='passed'?'✓':r.status==='failed'?'!':'·'}</span><div><b>{r.name}</b><p>{r.detail}</p></div></div>)}</div><div className="assistant-safety"><ShieldCheck size={15}/> A passed evidence check is not a production guarantee. Apply a lab-only fix, then replay the scenario to evaluate the simulated regression check.</div></section>}
 <section className="panel diagnostic-results"><div className="panel-head"><div><h2>Real HTTP regression checks</h2><p>Send actual HTTP requests to allowlisted local demo endpoints and assert their responses</p></div><button className="btn primary" disabled={httpBusy} onClick={async()=>{setHttpBusy(true);setHttpError('');setHttpResult(null);try{setHttpResult(await request('/regression/http-checks',{method:'POST'}))}catch(e){setHttpError(e.message)}finally{setHttpBusy(false)}}}><Play size={15}/>{httpBusy?'Running HTTP tests…':'Run local HTTP tests'}</button></div><div className="lab-warning"><ShieldCheck size={17}/><div><b>Loopback-only test target</b><p>Tests call the local health, data, registration, and login endpoints. A unique temporary demo user is created; no external host or production system is contacted.</p></div></div>{httpError&&<p className="assistant-error">{httpError}</p>}{httpResult&&<><div className="diagnostic-summary"><div><b>{httpResult.summary?.passed||0}</b><small>passed</small></div><div><b>{httpResult.summary?.failed||0}</b><small>failed</small></div><div><b>{httpResult.results?.length||0}</b><small>HTTP assertions</small></div></div><div className="diagnostic-list">{(httpResult.results||[]).map((r,i)=><div className="diagnostic-case" key={r.name}><span className={'diagnostic-result '+r.status}>{r.status==='passed'?'✓':'!'}</span><div><b>{r.name}</b><p>{r.detail}</p><small>{r.path}{r.http_status?` · HTTP ${r.http_status}`:''}</small></div></div>)}</div><p className="muted-note">Run ID: {httpResult.id} · {httpResult.overall}. Results are saved in local verification history.</p></>}</section>
 <section className="panel diagnostic-results"><div className="panel-head"><div><h2>Before-and-after verification</h2><p>Capture the current local HTTP behavior, then compare the same checks after a change or fix.</p></div><span className="tiny-count">STAGE 12</span></div><div className="lab-warning"><ShieldCheck size={17}/><div><b>Local demo API only</b><p>The baseline is a snapshot of current test outcomes, not an assumed healthy state. A comparison flags tests that regress, improve, or remain failing.</p></div></div><div className="heading-actions" style={{marginBottom:16}}><button className="btn secondary" disabled={compareBusy} onClick={async()=>{setCompareBusy(true);setCompareError('');setCompareResult(null);try{const r=await request('/regression/baseline',{method:'POST'});setBaselineResult(r.snapshot)}catch(e){setCompareError(e.message)}finally{setCompareBusy(false)}}}><Database size={15}/> Capture baseline</button><button className="btn primary" disabled={compareBusy} onClick={async()=>{setCompareBusy(true);setCompareError('');try{setCompareResult(await request('/regression/compare',{method:'POST'}))}catch(e){setCompareError(e.message)}finally{setCompareBusy(false)}}}><Play size={15}/>{compareBusy?'Comparing…':'Run after-change comparison'}</button></div>{compareError&&<p className="assistant-error">{compareError}</p>}{baselineResult&&<p className="muted-note">Latest baseline: {baselineResult.id} · {new Date(baselineResult.created_at).toLocaleString()} · {baselineResult.summary?.passed||0} passed / {baselineResult.summary?.failed||0} failed</p>}{compareResult&&<><div className="panel-head"><div><h3>Comparison report</h3><p>{compareResult.id} · {new Date(compareResult.created_at).toLocaleString()}</p></div><span className={'diagnostic-status '+(compareResult.overall==='stable'||compareResult.overall==='improved'?'passed':compareResult.overall==='regression-detected'?'failed':'review')}>{compareResult.overall}</span></div><div className="diagnostic-summary">{Object.entries(compareResult.summary||{}).map(([k,v])=><div key={k}><b>{v}</b><small>{k.replace('-',' ')}</small></div>)}</div><div className="diagnostic-list">{(compareResult.comparisons||[]).map((r)=><div className="diagnostic-case" key={r.name}><span className={'diagnostic-result '+(r.status==='stable'||r.status==='improved'?'passed':r.status==='regression'?'failed':'review')}>{r.status==='stable'?'✓':r.status==='improved'?'↑':r.status==='regression'?'!':'·'}</span><div><b>{r.name}</b><p>{r.detail}</p><small>Before: {r.before_status??'—'} ({r.before_result??'—'}) · After: {r.after_status??'—'} ({r.after_result??'—'})</small></div></div>)}</div>{compareResult.limitations?.map((x,i)=><p className="muted-note" key={i}>{x}</p>)}</>}</section>
 <section className="panel diagnostic-results"><div className="panel-head"><div><h2>Incident-specific verification report</h2><p>Combine this incident's evidence, targeted checks, replay state, and local HTTP regression results into one auditable report.</p></div><span className="tiny-count">STAGE 13</span></div><div className="lab-warning"><ShieldCheck size={17}/><div><b>Reviewable demo verification</b><p>This report connects the selected incident to test and fix history. It clearly distinguishes a successful demo replay from production verification.</p></div></div><div className="heading-actions" style={{marginBottom:16}}><button className="btn primary" disabled={!selected||incidentVerifyBusy} onClick={async()=>{setIncidentVerifyBusy(true);setIncidentVerifyError('');setIncidentReport(null);try{setIncidentReport(await request(`/incidents/${selected}/verify-regression`,{method:'POST'}))}catch(e){setIncidentVerifyError(e.message)}finally{setIncidentVerifyBusy(false)}}}><ClipboardCheck size={15}/>{incidentVerifyBusy?'Building report…':'Generate incident verification report'}</button><button className="btn secondary" disabled={!selected||incidentVerifyBusy} onClick={async()=>{setIncidentVerifyError('');try{setIncidentReport(await request(`/incidents/${selected}/verification-report`))}catch(e){setIncidentVerifyError(e.message)}}}>Load latest report</button></div>{incidentVerifyError&&<p className="assistant-error">{incidentVerifyError}</p>}{incidentReport&&<><div className="panel-head"><div><h3>{incidentReport.incident?.title||incidentReport.incident_id}</h3><p>{incidentReport.id} · {new Date(incidentReport.created_at).toLocaleString()}</p></div><span className={'diagnostic-status '+(incidentReport.overall==='verified-in-demo'?'passed':incidentReport.overall==='regression-detected'||incidentReport.overall==='http-checks-failed'?'failed':'review')}>{incidentReport.overall}</span></div><p>{incidentReport.summary}</p><div className="diagnostic-summary"><div><b>{incidentReport.incident?.evidence_count??0}</b><small>incident evidence</small></div><div><b>{incidentReport.targeted_diagnostics?.summary?.passed??0}</b><small>targeted checks passed</small></div><div><b>{incidentReport.local_http_regression?.summary?.passed??0}/{incidentReport.local_http_regression?.results?.length??0}</b><small>HTTP assertions passed</small></div><div><b>{incidentReport.incident?.replay_passed===true?'Passed':'Not passed'}</b><small>incident replay</small></div></div><h3>Evidence snapshot</h3><div className="diagnostic-list">{(incidentReport.evidence_snapshot||[]).slice(-8).map((e,i)=><div className="diagnostic-case" key={e.id||i}><span className={'diagnostic-result '+(e.level==='error'?'failed':'review')}>{e.level==='error'?'!':'·'}</span><div><b>{e.source||e.kind||'Evidence'}</b><p>{e.message}</p><small>{e.timestamp||''}</small></div></div>)}</div>{incidentReport.latest_before_after_comparison&&<p className="muted-note">Latest global before/after comparison: {incidentReport.latest_before_after_comparison.overall}. It may not correspond to this incident's fix.</p>}{(incidentReport.limitations||[]).map((x,i)=><p className="muted-note" key={i}>{x}</p>)}</>}</section>
 <section className="panel diagnostic-guidance"><div className="panel-head"><div><h2>Recommended workflow</h2><p>Keep remediation reviewable</p></div></div><div className="workflow">{[['01','Generate an incident','Choose a fault in the Fault Injection Lab.'],['02','Run diagnostics','Inspect evidence checks and any warnings.'],['03','Apply a lab-only fix','Review the proposed remediation before recording it.'],['04','Replay and verify','Run the replay, then run diagnostics again.']].map(x=><div className="workflow-row" key={x[0]}><span>{x[0]}</span><div><b>{x[1]}</b><small>{x[2]}</small></div><ChevronRight size={15}/></div>)}</div></section></>
}
